local ActivityMidFestivalUtils = {}

function ActivityMidFestivalUtils.ShowTipsCountDown(targetNode, title, description, rare, id, isShowNumText)
    ResourceModule.LoadGameObjectAsync("Prefabs/ActivityMidFestival/12000201/MidFestivalStaminaTipsCountdown.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
            go.name = "StaminaTipsCountdown"
            if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
                local script = GetLuaBehaviour(go, "Game.Activity.MidFestival.MidFestivalStaminaTipsCountDown")
                if not KTool.IsNull(script) then
                    script.Env:RefreshBoardByContent(title, description, rare, id, isShowNumText)
                    script.Env:FixBoardPosition(targetNode)
                end
            end
        end
    end, true, UIModule.RootCanvas.transform)
end

function ActivityMidFestivalUtils.GetActivityScheduleVo()
    ---@type ActivityMidFestivalComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityDojo = comp:GetActivityDojo()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6082, "MidFestivalActivityScheduleVo", activityDojo.activityContentId)
    return vo
end

---@return ActivityMidFestivalMgr
function ActivityMidFestivalUtils.GetMidFestivalMgr()
    return ActivityMidFestivalMgr:GetInstance()
end

return ActivityMidFestivalUtils
